"""Configuration for the local (in-process) retrieval backend."""

from enum import Enum
from typing import Literal, Optional

from pydantic import BaseModel, Field


class SearchMode(str, Enum):
    """Retrieval mode used at query time."""

    VECTOR = "vector"
    HYBRID = "hybrid"


class ChunkingConfig(BaseModel):
    """Knobs controlling how pages are chunked."""

    chunk_size: int = Field(default=512, description="Approximate tokens per chunk.")
    chunk_overlap: int = Field(default=64, description="Approximate token overlap.")


class EmbedConfig(BaseModel):
    """Knobs controlling embedder model."""

    embed_engine: Literal["fastembed"] = Field(
        default="fastembed",
        description="Embedding engine. Only fastembed (ONNX runtime, no torch).",
    )
    embed_model: str = Field(
        default="BAAI/bge-small-en-v1.5",
        description="Embedding model name, as fastembed knows it.",
    )
    embed_cache_dir: Optional[str] = Field(
        default=None,
        description="Local dir to load/cache the embedding model from. CI "
        "populates this so the runtime never downloads on the query path.",
    )
    index_batch_size: int = Field(
        default=16, description="Batch size when embedding index docs for vector DB."
    )


class LocalRetrievalConfig(BaseModel):
    """Configuration for the local in-process retrieval backend."""

    vector_store: Literal["lancedb"] = Field(
        default="lancedb",
        description="Vector store backend. Only 'lancedb' today; swappable seam.",
    )
    embedder: EmbedConfig = Field(default_factory=EmbedConfig)
    top_k: int = Field(default=5, description="Number of chunks to retrieve.")
    index_cache_dir: str = Field(
        default=".retrieval_index",
        description="Directory for cached vector-store tables: one subfolder "
        "per corpus, then per (embed_engine, embed_model).",
    )
    topic_filter: Optional[str] = Field(
        default=None,
        description="Restrict retrieval to a topic (e.g. 'framework' | 'studio').",
    )
    search_mode: SearchMode = Field(default=SearchMode.VECTOR)
